#!/bin/sh
# Static validation of nftables commands generated by fwb_nft.
# Does not execute or install the firewall ruleset.
#
# The generated script stages three nft -f transactions through heredocs:
#   FWB_NFT_START_BASE + FWB_NFT_RULESET  (the "start" activation,
#       preceded at run time by the staged deletes and address tables;
#       the ruleset may be split into several FWB_NFT_RULESET segments,
#       separated by the run-time wrapper shell blocks)
#   FWB_NFT_BLOCK_BASE + FWB_NFT_BLOCK    (the emergency "block" policy)
#   FWB_NFT_STOP                          (empty FWB-owned tables batch)
# Every heredoc body is validated here, and rules may only reference
# chains that the matching transaction declared before them.
# Wrapper blocks for dynamic interface addresses and run-time DNS names
# run OUTSIDE the ruleset heredoc, appending their resolved copies into
# the same open transaction through small per-rule FWB_NFT_DYNRULE
# heredocs; those bodies are validated by the same rule checks.
set -eu
[ "$#" -gt 0 ] || { echo 'Usage: check-nft-output.sh SCRIPT.fw ...' >&2; exit 2; }
for fw in "$@"; do
    [ -s "$fw" ] || { echo "Empty nft script: $fw" >&2; exit 1; }
    sh -n "$fw" || { echo "Invalid shell wrapper: $fw" >&2; exit 1; }
    awk '
    function fail(msg) { print FILENAME ":" NR ": " msg > "/dev/stderr"; bad=1 }
    # Reload must enter the atomic start path directly. Stopping first
    # removes active FWB protection before the replacement is ready.
    /^[[:space:]]*reload\)[[:space:]]*$/ { in_reload=1; reload_count++; next }
    in_reload && /^[[:space:]]*;;[[:space:]]*$/ { in_reload=0; next }
    in_reload && /^[[:space:]]*#/ { next }
    in_reload && /(stop_action|\$0[[:space:]]+stop|"\$0"[[:space:]]+stop)/ {
        fail("reload removes active firewall policy before replacement")
        next
    }
    in_reload && /"\$0"[[:space:]]+start/ { reload_starts++; next }
    # No FWB operation may erase unrelated nftables rules or tables.
    /^[[:space:]]*(\$NFT[[:space:]]+)?flush[[:space:]]+ruleset([[:space:]]|$)/ {
        fail("global nftables flush forbidden: " $0); next
    }
    # ---------------- heredoc section tracking ----------------
    sec == "" && /<<FWB_NFT_START_BASE/ { sec="start"; open_start++; next }
    sec == "" && /<<FWB_NFT_BLOCK_BASE/ { sec="block_base"; open_block_base++; next }
    sec == "" && /<<.FWB_NFT_BLOCK([^A-Za-z0-9_]|$)/ {
        sec="block_rules"; open_block++; next
    }
    sec == "" && /<<FWB_NFT_RULESET/ { sec="ruleset"; open_ruleset++; next }
    sec == "" && /<<FWB_NFT_DYNRULE/ {
        # Run-time wrapper loops (dynamic interface addresses, run-time
        # DNS names) stage with a guarded append into the SAME open
        # transaction: every loop value must pass the rule checks below,
        # and the emitter must never run unguarded, or an empty variable
        # value could corrupt the staged transaction.
        n = split($0, seg, " && ")
        ok = (n >= 2)
        for (s = 1; s < n; s++)
            if (seg[s] !~ /^test -n "\$[A-Za-z0-9_]+"$/) ok = 0
        if (seg[n] !~ /^cat >> "\$FWB_NFT_TXN" <<FWB_NFT_DYNRULE[[:space:]]*$/) ok = 0
        if (!ok) fail("unsafe run-time wrapper emitter: " $0)
        sec="dyn"; open_dyn++; next
    }
    sec == "" && /<<.FWB_NFT_STOP/ { sec="stop"; open_stop++; next }
    /^(FWB_NFT_START_BASE|FWB_NFT_BLOCK_BASE|FWB_NFT_BLOCK|FWB_NFT_RULESET|FWB_NFT_DYNRULE|FWB_NFT_STOP)[[:space:]]*$/ {
        if (sec == "") fail("nft heredoc end marker outside heredoc: " $0)
        sec=""
        next
    }
    sec == "" { next }
    sec == "stop" {
        # The stop transaction stages only the deletes from
        # fwb_nft_begin_transaction; its heredoc body is comments only.
        if ($0 !~ /^[[:space:]]*(#|$)/)
            fail("unexpected command inside stop heredoc: " $0)
        next
    }
    # -------- base chain declarations (start and block branches) --------
    sec == "start" || sec == "block_base" {
        if ($0 ~ /^[[:space:]]*$/ || $0 ~ /^[[:space:]]*#/) next
        n=split($0, part, /[[:space:]]+/)
        if ($1 != "add") { fail("non-native command inside declaration heredoc: " $0); next }
        if ($2 == "table" && n>=4) {
            family=part[3]; tab=part[4]
            if (tab !~ /^(filter|nat|mangle)$/) fail("unowned nft table: " tab)
            dkey=sec SUBSEP family SUBSEP tab
            if (dtable[dkey]) fail("duplicate table declaration: " family " " tab)
            dtable[dkey]=1
            if (sec=="start") start_table[family SUBSEP tab]=1
            else block_table[family SUBSEP tab]=1
            next
        }
        if ($2 == "chain" && n>=5) {
            family=part[3]; tab=part[4]; chain=part[5]
            key=family " " tab " " chain
            dkey=sec SUBSEP family SUBSEP tab SUBSEP chain
            if (sec=="start" && !start_table[family SUBSEP tab])
                fail("chain before table: " key)
            if (sec=="block_base" && !block_table[family SUBSEP tab])
                fail("chain before table: " key)
            if (dchain[dkey]) fail("duplicate chain declaration: " key)
            dchain[dkey]=1
            # Base chains carry a braced { type ... hook ... } definition
            # with an explicit policy; the fwbuilder-owned tables never
            # leave a base chain without a defined policy.
            if ($0 !~ /\{/) fail("base chain without hook definition: " key)
            if (tab=="nat" && $0 !~ /type nat hook/) fail("NAT base chain missing nat hook: " key)
            if (tab=="mangle" && $0 !~ /type (filter|route) hook/) fail("mangle base chain missing hook: " key)
            if ($0 !~ /policy (drop|accept)[[:space:]]*;/) fail("base chain without policy: " key)
            if (sec=="start") start_chain[family SUBSEP tab SUBSEP chain]=1
            else block_chain[family SUBSEP tab SUBSEP chain]=1
            next
        }
        fail("unrecognized declaration command: " $0); next
    }
    # -------- emergency block management rules --------
    sec == "block_rules" {
        if ($0 ~ /^[[:space:]]*$/ || $0 ~ /^[[:space:]]*#/) next
        n=split($0, part, /[[:space:]]+/)
        if ($1!="add" || $2!="rule" || n<6) { fail("non-native command inside block heredoc: " $0); next }
        family=part[3]; tab=part[4]; chain=part[5]
        key=family " " tab " " chain
        if (tab !~ /^(filter|nat|mangle)$/) fail("unowned nft table referenced: " tab)
        if (!block_chain[family SUBSEP tab SUBSEP chain]) fail("block rule references undefined chain: " key)
        if ($0 ~ /[io]ifname[[:space:]]+"[^"]*\+/) fail("iptables-style interface wildcard: " $0)
        if ($0 ~ /[io]ifname[[:space:]]+"\*"/) fail("bare interface wildcard: " $0)
        if ($0 ~ /(^|[[:space:]])(--[[:alnum:]]+|-j|-m)([[:space:]]|$)/)
            fail("iptables option in native rule: " $0)
        # The block heredoc is quoted; any dollar sign would reach nft -f.
        if ($0 ~ /\$/) fail("unexpanded variable in block transaction: " $0)
        next
    }
    # -------- policy rules (the "start" transaction rule heredoc) --------
    {
        if ($0 ~ /^[[:space:]]*$/ || $0 ~ /^[[:space:]]*#/) next
        # Shell loops executing at activation time live OUTSIDE the staged
        # heredocs as small FWB_NFT_DYNRULE wrapper blocks. Text inside a
        # staged heredoc is read verbatim by "nft -f": loop keywords would
        # be syntax errors (or worse, semi-valid rules after the
        # variables had already expanded empty while the heredoc was
        # read).
        if ($0 ~ /^[[:space:]]*(for|do|done|while)([[:space:]]|$)/) {
            fail("shell loop keyword leaked into nft heredoc: " $0); next
        }
        n=split($0, part, /[[:space:]]+/)
        if ($2=="table") { fail("table declared outside fwb_nft_declare_base_chains: " $0); next }
        # The iptables-era wrapper emitted "test -n ... && <command>"; the
        # atomic backend stages run-time values through FWB_NFT_DYNRULE
        # blocks outside the heredoc, so a test guard must never remain
        # inside staged text.
        if ($1=="test") {
            fail("shell test guard leaked into nft heredoc: " $0); next
        }
        # The iptables backend silently printed rules whose address object
        # or unnumbered interface resolved to an empty operand, widening
        # the match to "any". nft -f rejects such rules with a syntax
        # error (OpenWrt appliance imports hit this). The compiler aborts
        # on empty operands now; a generated script must never contain
        # one: a saddr/daddr keyword followed by two spaces means the
        # operand slot is empty.
        if ($0 ~ /(ip6? (saddr|daddr))[[:space:]][[:space:]]/) {
            fail("empty ip saddr/daddr operand in rule: " $0); next
        }
        if ($1!="add") { fail("non-native command inside nft heredoc: " $0); next }
        # Hookless chains are ordinary jump targets which the native
        # compiler creates on demand for negation and NAT branching.
        # Base chains live in fwb_nft_declare_base_chains, never here.
        if ($2=="chain" && n>=5) {
            family=part[3]; tab=part[4]; chain=part[5]
            key=family SUBSEP tab SUBSEP chain
            if (tab !~ /^(filter|nat|mangle)$/) fail("unowned nft table: " tab)
            if (chains_here[key]) fail("duplicate chain: " family " " tab " " chain)
            if ($0 ~ /\{/) fail("base chain definition inside ruleset: " family " " tab " " chain)
            chains_here[key]=1
            # The ruleset heredoc precedes the declaration function in the
            # generated file; the table is verified at END.
            need_chain_table[key]=family SUBSEP tab
            next
        }
        # Named dynamic hashlimit sets are nftables objects, not rules.
        # They must belong to an existing FWB table and be declared once.
        if ($2=="set" && n>=6) {
            family=part[3]; tab=part[4]; setname=part[5]
            key=family SUBSEP tab SUBSEP setname
            if (tab !~ /^(filter|mangle)$/) fail("unowned nft set table: " tab)
            if (setname !~ /^fwb_[[:alnum:]_]+$/) fail("invalid FWB set name: " setname)
            if (sets[key]++) fail("duplicate set declaration: " family " " tab " " setname)
            if ($0 !~ /[[:space:]]\{[[:space:]]*type[[:space:]]+/ ||
                $0 !~ /;[[:space:]]*\}[[:space:]]*$/)
                fail("malformed named set declaration: " family " " tab " " setname)
            need_set_table[key]=family SUBSEP tab
            next
        }
        if ($2=="rule" && n>=6) {
            family=part[3]; tab=part[4]; chain=part[5]
            key=family SUBSEP tab SUBSEP chain
            need_rule_line[key]=$0
            if (tab !~ /^(filter|nat|mangle)$/) fail("unowned nft table referenced: " tab)
            if ($0 ~ /[io]ifname[[:space:]]+"[^"]*\+/) fail("iptables-style interface wildcard: " $0)
            if ($0 ~ /[io]ifname[[:space:]]+"\*"/) fail("bare interface wildcard: " $0)
            if ($0 ~ /(^|[[:space:]])(--[[:alnum:]]+|-j|-m)([[:space:]]|$)/)
                fail("iptables option in native rule: " $0)
            if ($0 ~ /\$/) {
                # fwbuilder emits $i_<iface> (dynamic interface addresses,
                # attached networks), $at_<name> (run-time address tables)
                # and $dn_<name> (run-time DNS names) shell variables.
                # Those variables are only ever legal inside a
                # FWB_NFT_DYNRULE wrapper body, where the wrapper loop has
                # assigned them and the guard has proven them non-empty
                # before the mini heredoc is read. Inside a plain ruleset
                # heredoc the shell expands them while the heredoc is
                # being read: unwrapped placeholders silently widen the
                # match to an empty operand, exactly like the OpenWrt
                # DNSName regression. Reject them there; any other dollar
                # is an unexpanded leftover everywhere.
                probe=$0
                gsub(/\$(i|at|dn)_[A-Za-z0-9_]+/, "", probe)
                if (probe ~ /\$/) fail("unexpanded variable in native ruleset: " $0)
                if (sec == "ruleset")
                    fail("run-time variable outside FWB_NFT_DYNRULE wrapper: " $0)
            }
            rules++
            next
        }
        fail("unrecognized nft command: " $0)
    }
    END {
        if (reload_count!=1 || reload_starts!=1 || in_reload)
            fail("reload must invoke atomic start exactly once without stop")
        if (open_start!=1 || sec!="") fail("expected exactly one complete FWB_NFT_START_BASE")
        if (open_ruleset<1) fail("expected at least one complete FWB_NFT_RULESET")
        if (open_block_base!=1) fail("expected exactly one complete FWB_NFT_BLOCK_BASE")
        if (open_block!=1) fail("expected exactly one complete FWB_NFT_BLOCK")
        if (open_stop!=1) fail("expected exactly one complete FWB_NFT_STOP")
        if (rules<1) fail("native ruleset contains no rules")
        # The ruleset heredoc precedes the declaration function in the
        # generated file, so references are verified once the whole
        # script has been parsed.
        for (key in need_chain_table)
            if (!start_table[need_chain_table[key]])
                fail("chain before table: " key)
        for (key in need_set_table)
            if (!start_table[need_set_table[key]])
                fail("set before table: " key)
        for (key in need_rule_line)
            if (!chains_here[key] && !start_chain[key])
                fail("rule references undefined chain: " need_rule_line[key])
        if (!bad) print "Native nftables structure OK: " FILENAME " (" rules " rules)"
        exit bad ? 1 : 0
    }' "$fw" || exit 1
done
